#![cfg(unix)]
use moloch_live_runtime::{dispatch::DispatchLog,fundamental_policy::{ReviewFile,SourceFile},paper5_runtime::*,value_surface::{mapping_sha256,sha256}};
use serde_json::{json,Value};
use std::collections::{BTreeMap,BTreeSet};
#[path="support/value_surface_fixture.rs"]mod support;
use support::*;
fn save(f:&F,name:&str,bytes:&[u8])->SourceFile{let path=f.root.join(name);std::fs::write(&path,bytes).unwrap();SourceFile{path,sha256:sha256(bytes)}}
fn settings(f:&F)->Settings{
 let artifact=save(f,"atlas.json",&f.bytes);let authority=save(f,"approval.json",&serde_json::to_vec(&json!({"version":1,"trustedReviewSha256":f.trusted_reviews})).unwrap());
 let bindings=(0..5).map(|i|{let review=save(f,&format!("review-{i}.json"),&serde_json::to_vec(&f.reviews[i]).unwrap());let source_files=f.originals[i].iter().enumerate().map(|(j,b)|save(f,&format!("source-{i}-{j}.bin"),b)).collect();let mapping=save(f,&format!("mapping-{i}.json"),&serde_json::to_vec(&f.mappings[i]).unwrap());BindingFiles{review:ReviewFile{path:review.path,file_sha256:review.sha256,source_files},mapping}}).collect();
 Settings{version:1,approved_artifact_sha256:[artifact.sha256.clone()].into(),artifact,authority_path:authority.path,authority_sha256:authority.sha256,approved_mapping_sha256:f.mappings.iter().map(|m|mapping_sha256(m).unwrap()).collect(),bindings,router:RouterSettings{strategy_sha256:"a".repeat(64),order_lifetime_ms:30000,model_uncertainty_per_share:1000,terminal_tail_charge_per_share:1000,write_charge_per_order:100,capital_charge_per_million_unit_ms:0},curve:Some(moloch_live_runtime::election_curve::FitPolicy{factor_id:"national".into(),minimum_races:3,maximum_depth_weight:20,maximum_factor_abs:3.,minimum_residual_micros:10000}),hedges:Some(moloch_live_runtime::election_curve::HedgeLimits{maximum_quantity_per_leg:20,maximum_gross_funding:100000000,maximum_absolute_factor_exposure:0,minimum_model_gain:1,tail_probability_ppm:50000,maximum_tail_loss:0}),allow_research_diagnostics:true,maximum_proposals:32,maximum_dispatch_records:20000,maximum_bank_sequence:1_000_000}
}
fn nodes(f:&F)->BTreeMap<String,baal_transport_service::Receipt>{f.receipts.iter().enumerate().map(|(i,r)|((101+i).to_string(),r.clone())).collect()}
fn evaluate(r:&Runtime,f:&F,log:&DispatchLog,at:u64)->Diagnostic{r.evaluate(&f.bank,&f.scope,log,&nodes(f),&BTreeMap::new(),&BTreeSet::new(),at)}
#[test]fn real_session_retained_sources_flow_through_surface_curve_and_router_without_money_changes(){let f=F::new();let cfg=settings(&f);let r=Runtime::load(&cfg).unwrap();let log=DispatchLog::open(&f.root.join("p5-dispatch.ndjson")).unwrap();let head=f.bank.durable_head();let financial=f.bank.engine().report().unwrap();let out=evaluate(&r,&f,&log,NOW);assert_eq!(out.state,"proposal_only");assert_eq!(out.routing.len(),5);assert!(out.routing.iter().any(|r|r["candidates"].as_array().unwrap().len()==3));assert!(out.curve.is_some());assert_eq!(out.hedge_ideas.len(),1);assert!(!out.execution_authority);assert!(!out.financial_state_changed);assert_eq!(out.source_files_read_during_evaluation,0);assert_eq!(f.bank.durable_head(),head);assert_eq!(f.bank.engine().report().unwrap(),financial);}
#[test]fn originals_are_cached_after_verified_setup_and_no_evaluation_source_file_reads_occur(){let f=F::new();let cfg=settings(&f);let r=Runtime::load(&cfg).unwrap();let hashes=r.original_source_hashes().clone();std::fs::remove_file(&cfg.artifact.path).unwrap();std::fs::remove_file(&cfg.authority_path).unwrap();for b in &cfg.bindings{std::fs::remove_file(&b.review.path).unwrap();std::fs::remove_file(&b.mapping.path).unwrap();for s in &b.review.source_files{std::fs::remove_file(&s.path).unwrap();}}let log=DispatchLog::open(&f.root.join("p5-dispatch.ndjson")).unwrap();let out=evaluate(&r,&f,&log,NOW);assert_eq!(out.state,"proposal_only");assert_eq!(out.source_files_read_during_evaluation,0);assert_eq!(r.original_source_hashes(),&hashes);assert!(!out.execution_authority,"cached proposal facts never replace final source/physical authority guards");}
#[test]fn research_and_expired_original_source_qualifications_are_honest_without_reactivation(){let f=F::new();let mut cfg=settings(&f);cfg.allow_research_diagnostics=false;let r=Runtime::load(&cfg).unwrap();let log=DispatchLog::open(&f.root.join("p5-dispatch.ndjson")).unwrap();let out=evaluate(&r,&f,&log,NOW);assert_eq!(out.state,"unavailable");assert_eq!(out.deferred[0]["reason"],"research_model_not_promoted");assert!(out.routing.is_empty());cfg.allow_research_diagnostics=true;let r=Runtime::load(&cfg).unwrap();let out=evaluate(&r,&f,&log,NOW+120000);assert_eq!(out.deferred[0]["reason"],"posterior_expired_original_clock");assert!(out.routing.is_empty());}
#[test]fn unknown_original_dispatch_blocks_proposals_without_becoming_zero_or_closed(){let f=F::new();let r=Runtime::load(&settings(&f)).unwrap();let mut log=DispatchLog::open(&f.root.join("p5-dispatch.ndjson")).unwrap();log.append(json!({"kind":"intent","qid":9000,"spec":{"method":"POST","endpoint":"/orders","body":{"tournamentId":"cup","exchangeId":"101","side":"yes","action":"buy","quantity":1,"price":0.4},"bodyJson":"{\"tournamentId\":\"cup\",\"exchangeId\":\"101\",\"side\":\"yes\",\"action\":\"buy\",\"quantity\":1,\"price\":0.4}"},"at":iso(NOW)})).unwrap();log.append(json!({"kind":"attempt","qid":9000,"at":iso(NOW),"captureAtMs":NOW,"nativeHead":f.bank.durable_head()})).unwrap();let out=evaluate(&r,&f,&log,NOW);assert_eq!(out.state,"deferred");assert!(out.routing.is_empty());assert!(!log.never_attempted(9000));assert!(!log.closed.contains(&9000));}
#[test]fn missing_or_changed_current_node_never_causes_a_new_api_read_or_foreign_mapping(){let f=F::new();let r=Runtime::load(&settings(&f)).unwrap();let log=DispatchLog::open(&f.root.join("p5-dispatch.ndjson")).unwrap();let out=r.evaluate(&f.bank,&f.scope,&log,&BTreeMap::new(),&BTreeMap::new(),&BTreeSet::new(),NOW);assert_eq!(out.state,"unavailable");assert_eq!(out.deferred.len(),5);assert!(out.routing.is_empty());let mut n=nodes(&f);n.get_mut("104").unwrap().data["root"]["contract_id"]=json!("other");let out=r.evaluate(&f.bank,&f.scope,&log,&n,&BTreeMap::new(),&BTreeSet::new(),NOW);assert!(out.routing.is_empty());assert!(out.deferred.iter().any(|d|d["reason"]=="SURFACE_CURRENT_CONTRACT_CHANGED"));assert_eq!(out.source_files_read_during_evaluation,0);}
#[test]fn original_source_tampering_and_unapproved_mapping_fail_at_setup(){let f=F::new();let mut cfg=settings(&f);std::fs::write(&cfg.bindings[0].review.source_files[1].path,b"changed original source").unwrap();assert!(Runtime::load(&cfg).is_err());cfg=settings(&f);cfg.approved_mapping_sha256.clear();assert!(Runtime::load(&cfg).is_err());cfg=settings(&f);cfg.approved_artifact_sha256.clear();assert!(Runtime::load(&cfg).is_err());}
#[test]fn proposal_count_and_diagnostic_work_bounds_are_enforced_without_native_mutation(){let f=F::new();let mut cfg=settings(&f);cfg.maximum_proposals=2;let r=Runtime::load(&cfg).unwrap();let log=DispatchLog::open(&f.root.join("p5-dispatch.ndjson")).unwrap();let out=evaluate(&r,&f,&log,NOW);let count=out.routing.iter().map(|r|r["candidates"].as_array().unwrap().len()).sum::<usize>()+out.hedge_ideas.len();assert!(count<=2);cfg.maximum_bank_sequence=1;let r=Runtime::load(&cfg).unwrap();let out=evaluate(&r,&f,&log,NOW);assert_eq!(out.deferred[0]["reason"],"diagnostic_work_bound");assert!(out.routing.is_empty());}
#[test]fn typed_settings_reject_unknown_fields_instead_of_treating_them_as_approval(){let f=F::new();let cfg=settings(&f);let mut v:Value=serde_json::to_value(cfg).unwrap();v["activate"]=json!(true);assert!(serde_json::from_value::<Settings>(v).is_err());}
